export function buildReviewPrompt(input) {
    return [
        `Repository: ${input.owner}/${input.repo}`,
        `Pull request: #${input.pullNumber}`,
        `Title: ${input.title}`,
        "",
        "Pull request body:",
        input.body.trim() || "(empty)",
        "",
        `Review scope: only review the latest commit ${input.headSha}.`,
        `Commit range: ${input.baseSha}...${input.headSha}`,
        "Do not review older commits in this pull request.",
        "Do not repeat general style advice. Focus only on issues introduced by this latest commit.",
        "",
        "Review like a senior staff engineer. Inspect the diff for:",
        "- Correctness bugs: broken control flow, invalid assumptions, edge cases, race conditions, state consistency, data loss, and behavior regressions.",
        "- Security vulnerabilities: injection, authz/authn mistakes, secret exposure, unsafe file/network access, dependency risks, and privilege escalation.",
        "- Performance regressions: accidental extra I/O, repeated API calls, memory growth, unnecessary serialization, unbounded loops, and slow paths in hot code.",
        "- Missing tests: absent coverage for changed behavior, error paths, boundary cases, security-sensitive paths, and regressions.",
        "- API design: confusing contracts, leaky abstractions, backward incompatible behavior, ambiguous naming, and poor caller ergonomics.",
        "- Encapsulation: logic placed in the wrong layer, mutable shared state, hidden coupling, and unnecessary exposure of internals.",
        "- Modularity: functions, classes, or modules doing too much; duplicated logic; unclear ownership; code that should be split or simplified.",
        "- Files that are too long: new code that makes a file harder to navigate, review, or test; recommend a split only when it directly improves maintainability.",
        "",
        "Review discipline:",
        "- Be actionable: every finding must explain the concrete risk and the smallest useful fix.",
        "- Be line-specific when the diff gives enough context; mention file/function names from the diff.",
        "- Do not invent problems. If there are no meaningful findings, say so.",
        "- Do not ask for broad rewrites unless the latest commit creates a clear maintainability risk.",
        "",
        "Return valid JSON only. Do not wrap it in Markdown fences.",
        "Use this exact shape:",
        "{",
        '  "summaryMarkdown": "Concise Markdown summary with high risk findings, medium risk findings, low risk suggestions, missing or weak tests, and verdict.",',
        '  "inlineComments": [',
        '    { "path": "relative/file/path.ts", "line": 12, "body": "Actionable line-specific comment." }',
        "  ]",
        "}",
        "For inlineComments:",
        "- Only include comments for lines added or changed in the latest commit diff.",
        "- Use the new-file path from the diff.",
        "- Use 1-based line numbers on the RIGHT side of the diff.",
        "- Keep body concise and actionable; Markdown suggestions are allowed when exact.",
        "- If no line-specific findings are needed, return an empty inlineComments array.",
        "",
        "Latest commit diff:",
        "```diff",
        input.diff,
        "```",
        "",
    ].join("\n");
}
